xql_query:
// ============================================================
// Rule: Cisco Switch – Múltiplos logins bem-sucedidos em vários switches (≥8 em 1h)
// Vendor: Cisco
// Objective:
// Detect activity associated with Cisco Switch – Múltiplos logins bem-sucedidos em vários switches (≥8 em 1h).
// Severity: SEV_040_HIGH
// Category: LATERAL_MOVEMENT
// ============================================================
// SANITIZED: Environment-specific values replaced with generic placeholders.
// MITRE ATT&CK:
// Tactic: TA0008 - Lateral Movement
// Technique: T1021 - Remote Services

dataset = cisco_switch_raw
| filter _raw_log contains "%SEC_LOGIN-5-LOGIN_SUCCESS"
| alter username = arrayindex(regextract(_raw_log, "[[]user: ([^]]+)[]]"), 0)
| filter not (username = "dna.cisco" or username = "<SERVICE_ACCOUNT_2>")
| bin _time span = 1h
| comp count_distinct(_final_reporting_device_ip) as switches,
       count() as logins
  by username, _time
| filter switches >= 8
| sort desc switches
